"""Render the completed fixed-subset UCSF diagnostic audit."""
from pathlib import Path
import json
root=Path(__file__).resolve().parents[1];out=root/'experiments/ucsf-training-diagnostics-001'
results=json.loads((out/'results.json').read_text());protocol=json.loads((out/'protocol.json').read_text())
if len(results)!=10 or not (out/'provenance.json').exists():raise ValueError('Audit not complete')
final=[r for r in results if r['epoch']==5];trajectory=[r for r in results if r['seed']==43 and r['mode']=='baseline']
collapsed=trajectory[-1];early=trajectory[:2]
summary={'purpose':'post hoc diagnostic analysis; no training or threshold change','evaluations':len(results),'patient_checkpoint_evaluations':sum(len(r['cases']) for r in results),'fixed_training_subset':protocol['training_patients'],'validation_patients':protocol['validation_patients'],'final_runs':[{'seed':r['seed'],'mode':r['mode'],'groups':r['groups']} for r in final],'seed43_baseline_history':[{'epoch':r['epoch'],'groups':r['groups'],'training_loss':r['training_loss'],'amp_skipped_updates':r['amp_skipped_updates']} for r in trajectory],'clinical_evaluation':False,'model_promoted':False,'limits':protocol['limits']}
(out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n',encoding='utf-8')
rows=''.join(f'<tr><td>{r["seed"]}</td><td>{r["mode"]}</td><td>{r["groups"]["train"]["mean_dice"]:.4f}</td><td>{r["groups"]["development_validation"]["mean_dice"]:.4f}</td><td>{r["groups"]["train"]["mean_fp_ml"]:.2f}</td><td>{r["groups"]["development_validation"]["mean_fp_ml"]:.2f}</td></tr>' for r in final)
history=''.join(f'<tr><td>{r["epoch"]}</td><td>{r["training_loss"]:.4f}</td><td>{r["groups"]["train"]["mean_dice"]:.4f}</td><td>{r["groups"]["development_validation"]["mean_dice"]:.4f}</td><td>{r["groups"]["train"]["max_probability"]:.4f}</td><td>{r["groups"]["development_validation"]["max_probability"]:.4f}</td><td>{r["amp_skipped_updates"]}</td></tr>' for r in trajectory)
sections=[]
for r in final:
    cases=''.join(f'<tr><td>{c["exam_id"]}</td><td>{c["role"]}</td><td>{c["probability"]["foreground"]["mean_probability"]:.4f}</td><td>{c["probability"]["background"]["mean_probability"]:.4f}</td><td>{c["probability"]["slices"]["fp_voxels_on_reference_empty_slices"]}</td><td>{c["probability"]["slices"]["reference_positive_with_empty_prediction"]}</td></tr>' for c in r['cases'])
    sections.append(f'<details><summary>Seed {r["seed"]} / {r["mode"]}: per-patient probability diagnostics</summary><div class="scroll"><table><tr><th>Patient</th><th>Role</th><th>Mean p on annotation</th><th>Mean p outside annotation</th><th>FP voxels on empty slices</th><th>Positive slices with empty output</th></tr>{cases}</table></div></details>')
(out/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>UCSF training diagnostics</title><style>body{font:16px system-ui;background:#101b2b;color:#ecf3fb;max-width:1200px;margin:30px auto;padding:20px}td,th{padding:10px;border-bottom:1px solid #456;text-align:left}a{color:#80ded0}.scroll{overflow:auto}details{margin:20px 0}summary{cursor:pointer}</style><h1>UCSF training diagnostics</h1><p>Six final checkpoints and the full five-epoch history of seed 43 baseline. Four training patients selected by a fixed identity hash and all four development-validation patients. Native metrics use threshold 0.5; no threshold tuning or model update.</p><h2>Final-checkpoint comparison</h2><div class="scroll"><table><tr><th>Seed</th><th>Run</th><th>Train subset Dice</th><th>Validation Dice</th><th>Train FP mL</th><th>Validation FP mL</th></tr>'''+rows+'</table></div><h2>Seed 43 baseline: checkpoint trajectory</h2><div class="scroll"><table><tr><th>Epoch</th><th>Training loss</th><th>Train Dice</th><th>Validation Dice</th><th>Train max p</th><th>Validation max p</th><th>AMP skips</th></tr>'+history+'</table></div><p>Training loss is the recorded epoch average before each update; diagnostics use the saved end-of-epoch checkpoint. They are not the same measurement. Original gradients were not logged, so AMP skip counts alone cannot establish the cause of a failure.</p>'+''.join(sections)+'<p>Probability means and histograms describe model scores, not calibrated certainty. Training results cover a fixed subset only. These reused development patients cannot establish external performance.</p><p><a href="summary.json">Summary</a> · <a href="results.json">Full metrics and histograms</a> · <a href="protocol.json">Selection policy</a> · <a href="provenance.json">Checksums</a></p></html>',encoding='utf-8')
print(json.dumps(summary,indent=2))
